from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
base_src=(ROOT/'tools/editorial/es_a2_189_198.py').read_text(encoding='utf-8')
tree=ast.parse(base_src)
ns={'copy':copy}
for node in tree.body:
    if isinstance(node,ast.FunctionDef) and node.name in {'make','verbs_pt'}:
        exec(compile(ast.Module(body=[node], type_ignores=[]), str(ROOT/'tools/editorial/es_a2_189_198.py'), 'exec'), ns)
make=ns['make']

def plan(n,t,focus,work,year,desc,v,vb,ex,sound,names,s1,s2):
    return {'n':n,'t':t,'focus':focus,'work':work,'year':year,'desc':desc,
            'v':[(a,b,c) for a,b,c in v],'vb':vb,'ex':sum(([a,b] for a,b in ex),[]),
            'sound':sound,'s1':[[names[i%2],*x] for i,x in enumerate(s1)],
            's2':[[names[i%2],*x] for i,x in enumerate(s2)]}

